import{_ as p,a0 as d,w as o,s as b,I as t,x as e,a1 as n,A as l,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"在 Ubuntu Linux 上安装 Deb 文件的 3 种方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu Linux 上安装 Deb 文件的 3 种方法 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu Linux 上安装 Deb 文件的 3 种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu Linux 上安装 Deb 文件的 3 种方法 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20190208 3 Ways to Install Deb Files on Ubuntu Linux","title":"在 Ubuntu Linux 上安装 Deb 文件的 3 种方法","tag":"202012","desc":""},"relativePath":"202012/20190208 3 Ways to Install Deb Files on Ubuntu Linux.md","filePath":"[post].md"}'),u={name:"202012/20190208 3 Ways to Install Deb Files on Ubuntu Linux.md"};function r(g,s,k,h,f,m){const i=d("Link");return o(),b("div",null,[s[38]||(s[38]=t("h1",{id:"在-ubuntu-linux-上安装-deb-文件的-3-种方法",tabindex:"-1"},[e("在 Ubuntu Linux 上安装 Deb 文件的 3 种方法 "),t("a",{class:"header-anchor",href:"#在-ubuntu-linux-上安装-deb-文件的-3-种方法","aria-label":"Permalink to “在 Ubuntu Linux 上安装 Deb 文件的 3 种方法”"},"​")],-1)),s[39]||(s[39]=t("blockquote",null,[t("p",null,"这篇初学者文章解释了如何在 Ubuntu 中安装 deb 软件包。它稍后也向你展示如何移除这些 deb 软件包。")],-1)),t("p",null,[s[1]||(s[1]=e("这是 Ubuntu 初学者系列的另一篇文章。如果你对 Ubuntu 很陌生，你可能会想知道 ",-1)),n(i,{href:"https://itsfoss.com/remove-install-software-ubuntu/"},{default:l(()=>[...s[0]||(s[0]=[e("如何安装应用程序",-1)])]),_:1}),s[2]||(s[2]=e("。",-1))]),s[40]||(s[40]=t("p",null,"最简单的方法是使用 Ubuntu 软件中心。在软件中心中搜索应用程序的名称并安装它。如果你能在软件中心中找到所有的应用程序，那么生活就太惬意了。但是，不幸的是，这是不可能的发生的。",-1)),s[41]||(s[41]=t("p",null,"一些软件包可以通过 DEB 软件包的形式获得。它们是以 .deb 扩展名为结尾的存档文件。你可以把 .deb 文件看作为 Windows 中的 .exe 文件。在 Windows 中，你双击 .exe 文件，它将开始安装过程。DEB 软件包也是非常类似的。",-1)),t("p",null,[s[4]||(s[4]=e("你可以从软件提供商网站的下载区域找到这些 DEB 软件包。例如，如果你想 ",-1)),n(i,{href:"https://itsfoss.com/install-chrome-ubuntu/"},{default:l(()=>[...s[3]||(s[3]=[e("在 Ubuntu 上安装 Google Chrome",-1)])]),_:1}),s[5]||(s[5]=e(" ，你可以从它的网站下载 Chrome 的 DEB 软件包。",-1))]),s[42]||(s[42]=a('<p>现在问题产生了，你将如何安装 deb 文件呢？在 Ubuntu 中有多种安装 DEB 软件包的方法。在这篇教程中，我将向你依次地展示它们。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/02/deb-packages-ubuntu.png?resize=800%2C450&amp;ssl=1" alt="在 Ubuntu 中安装 deb 文件"></p><h3 id="在-ubuntu-和基于-debian-的-linux-发行版中安装-deb-文件" tabindex="-1">在 Ubuntu 和基于 Debian 的 Linux 发行版中安装 .deb 文件 <a class="header-anchor" href="#在-ubuntu-和基于-debian-的-linux-发行版中安装-deb-文件" aria-label="Permalink to “在 Ubuntu 和基于 Debian 的 Linux 发行版中安装 .deb 文件”">​</a></h3><p>你可以选择一个 GUI 工具或一个命令行工具来安装一个 deb 软件包。你拥有选择权。</p><p>让我们继续看看如何安装 deb 文件。</p><h4 id="方法-1-使用默认的软件中心" tabindex="-1">方法 1: 使用默认的软件中心 <a class="header-anchor" href="#方法-1-使用默认的软件中心" aria-label="Permalink to “方法 1: 使用默认的软件中心”">​</a></h4><p>在 Ubuntu 中，最简单的方法是使用默认的软件中心。在这里你不必要做任何特别的事。只需要转到你所下载的 .deb 文件的文件夹下（它应该是 Downloads 文件夹），并在这个文件上双击。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/01/install-google-chrome-ubuntu-4.jpeg?resize=800%2C347&amp;ssl=1" alt="在 Ubuntu 上的 Google Chrome 的 deb 文件"></p><p>在已下载的 .deb 文件上双击以开始安装。</p><p>它将打开软件中心，并且你将看到安装软件时的选项。你所需要做的全部工作就是：点击安装按钮并输入你的登录密码。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/01/install-google-chrome-ubuntu-5.jpeg?resize=800%2C516&amp;ssl=1" alt="在 Ubuntu 软件中心中安装 Google Chrome"></p><p>.deb 文件的安装将通过软件中心来执行。</p><p>看，它甚至比在 Windows 中安装一个 .exe 文件更简单，不是吗？</p><h4 id="方法-2-使用-gdebi-应用程序来安装-deb-软件包及其依赖项" tabindex="-1">方法 2: 使用 Gdebi 应用程序来安装 deb 软件包及其依赖项 <a class="header-anchor" href="#方法-2-使用-gdebi-应用程序来安装-deb-软件包及其依赖项" aria-label="Permalink to “方法 2: 使用 Gdebi 应用程序来安装 deb 软件包及其依赖项”">​</a></h4><p>再提一次，如果事情总是进展顺利，生活可能会更简单一些。但是生活并不是我们熟知的那样。</p><p>现在，你已经知道 .deb 文件可以简单地通过软件中心来安装，接下来，让我告诉你一些软件包可能会遇到的依赖项的错误。</p><p>发生错误的原因是，一个程序可能依赖于另外一个软件包（库）。当开发者为你准备 DEB 软件包时，他/她可能会假设你的系统中已经有了所依赖的软件包（库）。</p><p>但是如果情况并不是这样的，你的系统没有这些所需要的软件包（库），你将遇到臭名昭著的“依赖项错误”。</p>',18)),t("p",null,[s[7]||(s[7]=e("软件中心不能处理这样的错误，因此你不得不使用另外一个名称为 ",-1)),n(i,{href:"https://itsfoss.com/gdebi-default-ubuntu-software-center/"},{default:l(()=>[...s[6]||(s[6]=[e("gdebi",-1)])]),_:1}),s[8]||(s[8]=e(" 的工具。",-1))]),s[43]||(s[43]=t("p",null,"gdebi 是一个轻量级的 GUI 应用程序，它只有安装 deb 软件包的一个用途。",-1)),s[44]||(s[44]=t("p",null,"它将识别依赖项，并尝试在安装 .deb 文件的同时安装这些依赖项。",-1)),s[45]||(s[45]=t("p",null,[t("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/01/gdebi-handling-dependency.jpg?ssl=1",alt:"gdebi 在安装 deb 软件包时处理依赖项"})],-1)),t("p",null,[s[10]||(s[10]=e("就我个人而言，我更喜欢使用 gdebi 而不是使用软件包中心来安装 deb 文件。它是一个轻量级应用程序，因此安装过程看起来更快一点。更多的信息，你可以阅读",-1)),n(i,{href:"https://itsfoss.com/gdebi-default-ubuntu-software-center/"},{default:l(()=>[...s[9]||(s[9]=[e("使用 gDebi ，并使其成为安装 DEB 软件包的默认设置",-1)])]),_:1}),s[11]||(s[11]=e("。",-1))]),s[46]||(s[46]=a('<p>你可以从软件中心或使用下面的命令来安装 gdebi ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gdebi</span></span></code></pre></div><h4 id="方法-3-在命令行中使用-dpkg-安装-deb-文件" tabindex="-1">方法 3: 在命令行中使用 dpkg 安装 .deb 文件 <a class="header-anchor" href="#方法-3-在命令行中使用-dpkg-安装-deb-文件" aria-label="Permalink to “方法 3: 在命令行中使用 dpkg 安装 .deb 文件”">​</a></h4>',3)),t("p",null,[s[13]||(s[13]=e("如果你想在命令行中安装 deb 软件包，你可以使用 ",-1)),s[14]||(s[14]=t("code",null,"apt",-1)),s[15]||(s[15]=e(" 命令或者 ",-1)),s[16]||(s[16]=t("code",null,"dpkg",-1)),s[17]||(s[17]=e(" 命令。实际上，",-1)),s[18]||(s[18]=t("code",null,"apt",-1)),s[19]||(s[19]=e(" 命令在底层上使用 ",-1)),n(i,{href:"https://help.ubuntu.com/lts/serverguide/dpkg.html.en"},{default:l(()=>[...s[12]||(s[12]=[e("dpkg",-1)])]),_:1}),s[20]||(s[20]=e(" 命令，但是 ",-1)),s[21]||(s[21]=t("code",null,"apt",-1)),s[22]||(s[22]=e(" 却更流行和易于使用。",-1))]),s[47]||(s[47]=a(`<p>如果你想对 deb 文件使用 <code>apt</code> 命令，像这样使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install path_to_deb_file</span></span></code></pre></div><p>如果你想对将要安装的 deb 软件包使用 <code>dpkg</code> 命令，在这里是如何完成它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg -i path_to_deb_file</span></span></code></pre></div><p>在这两个命令中，你应该使用你已下载的 deb 文件的路径和名称来替换 <code>path_to_deb_file</code> 。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/02/install-deb-file-with-dpkg.png?ssl=1" alt="在 Ubuntu 中使用 dpkg 命令安装 deb 文件"></p><p>如果你在安装 deb 软件包的过程中得到一个依赖项的错误，你可以使用下面的命令来修复依赖项的问题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -f</span></span></code></pre></div><h3 id="如何移除-deb-软件包" tabindex="-1">如何移除 deb 软件包 <a class="header-anchor" href="#如何移除-deb-软件包" aria-label="Permalink to “如何移除 deb 软件包”">​</a></h3><p>移除一个 deb 软件包也不是一件什么大事。并且，你不需要用于安装程序的原始的 deb 文件。</p><h4 id="方法-1-使用-apt-命令移除-deb-软件包" tabindex="-1">方法 1: 使用 apt 命令移除 deb 软件包 <a class="header-anchor" href="#方法-1-使用-apt-命令移除-deb-软件包" aria-label="Permalink to “方法 1: 使用 apt 命令移除 deb 软件包”">​</a></h4><p>你所需要的全部东西就是你所已安装程序的名称，接下来你可以使用 <code>apt</code> 或 <code>dpkg</code> 来移除这个程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove program_name</span></span></code></pre></div><p>现在，问题来了，在移除命令中，你如何找到你所需要使用的准确的程序名称？为此，<code>apt</code> 命令也有一个解决方案。</p><p>你可以使用 <code>apt</code> 命令找到所有已安装文件的列表，但是手动完成这一过程将会是一件令人头疼的事。因此，你可以使用 <code>grep</code> 命令来搜索你的软件包。</p><p>例如，在先前的部分中，我已安装 AppGrid 应用程序，但是如果我想知道准确的程序名称，我可以像这样使用一些东西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt list --installed | grep grid</span></span></code></pre></div><p>这将给予我全部的名称中含有 “grid” 的软件包，从这里，我可以得到准确的程序名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --installed | grep grid</span></span>
<span class="line"><span>WARNING: apt does not have a stable CLI interface. Use with caution in scripts.</span></span>
<span class="line"><span>appgrid/now 0.298 all [installed,local]</span></span></code></pre></div><p>正如你所看到的，一个名称为 “appgrid” 的软件包已经安装。现在，你可以在 <code>apt remove</code> 命令中使用这个程序名称。</p><h4 id="方法2-使用-dpkg-命令移除-deb-软件包" tabindex="-1">方法2: 使用 dpkg 命令移除 deb 软件包 <a class="header-anchor" href="#方法2-使用-dpkg-命令移除-deb-软件包" aria-label="Permalink to “方法2: 使用 dpkg 命令移除 deb 软件包”">​</a></h4><p>你可以使用 <code>dpkg</code> 来找到已安装程序的名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg -l | grep grid</span></span></code></pre></div><p>该输出将给予所有的名称中有 “grid” 的软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg -l | grep grid</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ii appgrid 0.298 all Discover and install apps for Ubuntu</span></span></code></pre></div><p>在上面的命令输出中的 <code>ii</code> 意味着软件包已经被正确地安装。</p><p>现在，你有了程序名称，你可以使用 <code>dpkg</code> 命令来移除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dpkg -r program_name</span></span></code></pre></div><p><strong>提示：更新 deb 软件包</strong></p><p>一些 deb 软件包 （像 Chrome）通过系统更新来提供其更新，但是对于大多数的其它的程序，你将不得不先移除已存在的程序，并在接下来安装更新的版本。</p><p>我希望这篇初学者指南能够帮助你在 Ubuntu 上安装 deb 软件包。我添加了移除部分，以便你可以更好地控制你所安装的程序。</p><hr>`,32)),t("p",null,[s[24]||(s[24]=e("via: ",-1)),n(i,{href:"https://itsfoss.com/install-deb-files-ubuntu"},{default:l(()=>[...s[23]||(s[23]=[e("https://itsfoss.com/install-deb-files-ubuntu",-1)])]),_:1})]),t("p",null,[s[29]||(s[29]=e("作者：",-1)),n(i,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...s[25]||(s[25]=[e("Abhishek Prakash",-1)])]),_:1}),s[30]||(s[30]=e(" 选题：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[26]||(s[26]=[e("lujun9972",-1)])]),_:1}),s[31]||(s[31]=e(" 译者：",-1)),n(i,{href:"https://github.com/robsean"},{default:l(()=>[...s[27]||(s[27]=[e("robsean",-1)])]),_:1}),s[32]||(s[32]=e(" 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[28]||(s[28]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[35]||(s[35]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[33]||(s[33]=[e("LCTT",-1)])]),_:1}),s[36]||(s[36]=e(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...s[34]||(s[34]=[e("Linux中国",-1)])]),_:1}),s[37]||(s[37]=e(" 荣誉推出",-1))])])}const T=p(u,[["render",r]]);export{y as __pageData,T as default};
